/**
 * Two model-backed actions form one typed research-then-write flow.
 * AgentAction declares each action and enforces its output schema. The host
 * resolves both seats to a scripted model, so this example needs no API key.
 * Agent.layerDefaults supplies the @smthrs/harness cell sandbox and steering.
 */
import * as NodeCrypto from "@effect/platform-node/NodeCrypto"
import { FlowEngine } from "@smthrs/engine"
import * as Agent from "@smthrs/agent/Agent"
import * as AgentAction from "@smthrs/agent/AgentAction"
import * as Budget from "@smthrs/agent/Budget"
import * as QuotaPolicy from "@smthrs/agent/QuotaPolicy"
import * as ScriptedJudge from "@smthrs/agent/ScriptedJudge"
import * as Seat from "@smthrs/agent/Seat"
import * as SeatResolver from "@smthrs/agent/SeatResolver"
import { Action, Flow, Interpreter } from "@smthrs/flow"
import * as Model from "@smthrs/model/Model"
import * as ModelEvent from "@smthrs/model/ModelEvent"
import type * as Route from "@smthrs/model/Route"
import { Node } from "@smthrs/plan"
import * as Registry from "@smthrs/registry/Registry"
import * as Effect from "effect/Effect"
import * as Layer from "effect/Layer"
import * as Option from "effect/Option"
import * as Schema from "effect/Schema"
import * as Stream from "effect/Stream"

const ResearchResult = Schema.Struct({
  summary: Schema.String,
  keyPoints: Schema.Array(Schema.String)
})

const ArticleResult = Schema.Struct({
  article: Schema.String,
  wordCount: Schema.Number
})

/** The research step: a model call whose answer must be a `ResearchResult`. */
export const Research = AgentAction.make("examples/Research", {
  payload: { topic: Schema.String },
  output: ResearchResult,
  seat: "anthropic:claude-sonnet-4-5",
  system: ["You are a research assistant. Provide concise, accurate summaries."],
  prompt: ({ topic }) => `Research the topic "${topic}" and report what matters about it.`
})

/** The writing step, which consumes the first step's typed fields. */
export const Write = AgentAction.make("examples/Write", {
  payload: {
    summary: Schema.String,
    keyPoints: Schema.Array(Schema.String)
  },
  output: ArticleResult,
  seat: "anthropic:claude-sonnet-4-5",
  system: ["You are a technical writer. Write clear, engaging content."],
  prompt: ({ keyPoints, summary }) =>
    `Write a short article from this research.\n\nSummary: ${summary}\n\nKey points:\n${
      keyPoints.map((point) => `- ${point}`).join("\n")
    }`
})

/**
 * The workflow. Nothing executes at plan time: `Research.call` records one
 * node, and `Node.andThen` feeds its planned result into `Write.call`.
 */
export const SimpleWorkflow = Flow.make("examples/SimpleWorkflow", {
  payload: { topic: Schema.String },
  success: ArticleResult,
  error: AgentAction.AgentFailure,
  body: ({ topic }) =>
    Research.call({ topic }).pipe(
      Node.bindPlanned((research) => Write.call({ summary: research.summary, keyPoints: research.keyPoints }))
    )
})

const prepared: Route.PreparedRequest = {
  routeId: "examples",
  protocolId: "examples",
  method: "POST",
  url: "https://example.invalid/v1/messages",
  publicHeaders: { "content-type": "application/json" },
  body: new TextEncoder().encode("{}"),
  bodyText: "{}"
}

/**
 * A scripted model: it answers each call with one cell whose `complete` output
 * is the JSON the declared schema asks for. A real seat streams the same events
 * from a provider.
 */
const scripted: Model.Model = Model.make({
  stream: (request) =>
    Stream.suspend(() => {
      const asked = request.system.map((part) => part.text).join("\n") + "\n" +
        request.messages.flatMap((message) =>
        message.content.flatMap((part) => (part.type === "text" ? [part.text] : []))
      ).join("\n")
      const answer = asked.includes("Write a short article")
        ? {
          article: "Durable workflows survive restarts because their steps are recorded, not remembered.",
          wordCount: 12
        }
        : {
          summary: "Durable workflows record every step so a restart resumes instead of repeating.",
          keyPoints: ["steps are journaled", "replay is deterministic"]
        }
      const cell = `ctx.done(${JSON.stringify(answer)})`
      return Stream.fromIterable([
        ModelEvent.ModelEvent.TextStart({ type: "text-start", id: "cell" }),
        ModelEvent.ModelEvent.TextDelta({ type: "text-delta", id: "cell", text: "```cell\n" + cell + "\n```" }),
        ModelEvent.ModelEvent.TextEnd({ type: "text-end", id: "cell" }),
        ModelEvent.ModelEvent.Settle({ type: "settle", stopReason: "stop" })
      ])
    })
})

/**
 * The host: one seat resolver, one registry, one sandbox budget, shared by
 * every model-backed action in the composition. Swapping this value is the
 * whole difference between this deterministic run and a live one.
 */
const host = AgentAction.layerHost({
  registry: Registry.makeNoop({
    list: () => Effect.succeed([]),
    visible: () => Effect.succeed([]),
    getOption: () => Effect.succeed(Option.none())
  }),
  limits: { calls: 8 },
  capabilityEnvelope: [],
  maxFrames: 4
})

const seats = SeatResolver.layer({
  resolve: (id) => Effect.succeed(Seat.make({
    id,
    modelId: Seat.modelIdOf(id),
    model: scripted,
    route: { prepare: () => Effect.succeed(prepared) },
    contextWindowTokens: 200_000
  }))
})

const SimpleWorkflowLayer = Layer.mergeAll(
  Research.layer,
  Write.layer,
  Interpreter.layer(SimpleWorkflow)
).pipe(
  Layer.provideMerge(Layer.mergeAll(host, seats, Agent.layer, ScriptedJudge.layer)),
  Layer.provideMerge(Layer.mergeAll(QuotaPolicy.layerUnclassified(), Budget.layerUnbounded())),
  Layer.provideMerge(Agent.layerDefaults),
  Layer.provideMerge(Action.layerImplementations),
  Layer.provideMerge(FlowEngine.layerMemory),
  Layer.provideMerge(NodeCrypto.layer)
)

/**
 * Runs the workflow. The result is `ArticleResult`-typed all the way out: no
 * caller parses model text.
 */
export const main: Effect.Effect<typeof ArticleResult.Type> = SimpleWorkflow.execute(
  { topic: "durable workflows" },
  { executionId: "agent-step-1" }
).pipe(
  Effect.provide(SimpleWorkflowLayer),
  Effect.orDie
)

/**
 * Port of examples/code-review-loop.jsx.
 *
 * Smithers shape: `<Ralph until={isApproved} maxIterations={3}
 * onMaxReached="return-last">` around a review-then-fix `<Sequence>`, plus a
 * final computed summary `<Task>` (an object literal, no agent). The fix step
 * is `skipIf={isApproved}` and consumes the review through `deps`.
 *
 * flows shape: a trampoline with `maxRounds: 3`. Each round reviews; a branch
 * either settles with `Flow.done` (the computed summary, built from real
 * plan-time data) or runs the fix action and hands off to the next round,
 * carrying the review's issue list as next-round payload. `skipIf` disappears:
 * the fix call only exists in the not-approved branch arm.
 *
 * Deviations:
 * - `onMaxReached: "return-last"` has no equivalent. When round 3 hands off,
 *   the engine fails the lineage with Flow.MaxRoundsExceeded instead of
 *   returning the last review (GAPS.md GAP-4).
 * - `Output.object({ schema })` on the review agent (provider-enforced JSON)
 *   has no equivalent; the action's `success` schema validates whatever the
 *   implementation returns, but nothing pushes the schema into the model
 *   request (GAPS.md GAP-2).
 * - Agent implementations are STUBs for the agent seam (GAPS.md GAP-1).
 */
import * as NodeCrypto from "@effect/platform-node/NodeCrypto"
import { FlowEngine } from "@smthrs/engine"
import { Action, Flow, Interpreter } from "@smthrs/flow"
import { Node } from "@smthrs/plan"
import * as Effect from "effect/Effect"
import * as Layer from "effect/Layer"
import * as Schema from "effect/Schema"

// zod: { approved: boolean, feedback: string, issues?: string[] }
const Review = Schema.Struct({
  approved: Schema.Boolean,
  feedback: Schema.String,
  issues: Schema.Array(Schema.String)
})

// zod: { filesChanged: string[], changesSummary: string }
const Fix = Schema.Struct({
  filesChanged: Schema.Array(Schema.String),
  changesSummary: Schema.String
})

// zod: { finalSummary: string, totalIterations: number }
const Summary = Schema.Struct({
  finalSummary: Schema.String,
  totalIterations: Schema.Number
})

const LoopPayload = Schema.Struct({
  directory: Schema.String,
  focus: Schema.String,
  iteration: Schema.Number,
  previousIssues: Schema.Array(Schema.String)
})

/** smithers: review Task, reviewAgent with tools {read, grep, bash}. */
export const ReviewCode = Action.make("code-review-loop/review", {
  payload: {
    directory: Schema.String,
    focus: Schema.String,
    previousIssues: Schema.Array(Schema.String)
  },
  success: Review
})

/** smithers: fix Task, fixAgent (describe-only), skipIf={isApproved}. */
export const DescribeFixes = Action.make("code-review-loop/fix", {
  payload: {
    feedback: Schema.String,
    issues: Schema.Array(Schema.String),
    directory: Schema.String
  },
  success: Fix
})

type ReviewLoopFlow = Flow.Flow<
  "code-review-loop/loop",
  typeof LoopPayload,
  typeof Summary,
  typeof Schema.Never,
  | Action.Requirement<"code-review-loop/review">
  | Action.Requirement<"code-review-loop/fix">
>

/**
 * smithers: the whole <Workflow>. The computed summary Task becomes the
 * `Flow.done` value in the approved arm: `iteration` is real payload data at
 * plan time, so the object literal is ordinary computation, exactly like the
 * smithers object-literal Task.
 */
export const ReviewLoop: ReviewLoopFlow = Flow.make("code-review-loop/loop", {
  payload: LoopPayload,
  success: Summary,
  maxRounds: 3,
  body: ({ directory, focus, iteration, previousIssues }) =>
    ReviewCode.call({ directory, focus, previousIssues }).pipe(
      Node.branch({
        if: (review) => review.approved,
        then: () =>
          Flow.done({
            finalSummary: "Code review passed - LGTM!",
            totalIterations: iteration
          }),
        else: (review) =>
          DescribeFixes.call({
            feedback: review.feedback,
            issues: review.issues,
            directory
          }).pipe(
            Node.andThen(() =>
              ReviewLoop.to({
                directory,
                focus,
                iteration: iteration + 1,
                // A planned reference: next round's payload carries this
                // round's issue list, replacing ctx.outputs.review[last].
                previousIssues: review.issues
              })
            )
          )
      })
    )
})

/** STUB agent seam (GAPS.md GAP-1). */
const implementations = Layer.mergeAll(
  ReviewCode.toLayer(({ previousIssues }) =>
    Effect.succeed(
      previousIssues.length > 0
        ? { approved: true, feedback: "LGTM", issues: [] as ReadonlyArray<string> }
        : {
          approved: false,
          feedback: "error handling is missing",
          issues: ["add error handling in src/index.ts"]
        }
    )
  ),
  DescribeFixes.toLayer(({ issues }) =>
    Effect.succeed({
      filesChanged: ["src/index.ts"],
      changesSummary: `Would fix: ${issues.join("; ")}`
    })
  )
)

const ReviewLoopLayer = Layer.mergeAll(
  implementations,
  Interpreter.layer(ReviewLoop)
).pipe(
  Layer.provideMerge(Action.layerImplementations),
  Layer.provideMerge(FlowEngine.layerMemory),
  Layer.provideMerge(NodeCrypto.layer)
)

export const main: Effect.Effect<typeof Summary.Type> = ReviewLoop.execute(
  { directory: "src", focus: "correctness", iteration: 1, previousIssues: [] },
  { executionId: "code-review-loop-1" }
).pipe(
  Effect.orDie,
  Effect.provide(ReviewLoopLayer)
)

/**
 * Port of examples/gate.jsx.
 *
 * Smithers shape: `<Loop until={satisfied} maxIterations={maxChecks}
 * onMaxReached="return-last">` around one checker `<Task timeoutMs={30_000}>`,
 * then a computed gate-summary `<Task>`.
 *
 * flows shape: a polling trampoline. Whether this round is the last allowed
 * check is plan-time payload data, so it selects the body's shape: the
 * exhausted round settles with a summary either way (this reproduces
 * `onMaxReached: "return-last"` exactly, as explicit topology instead of an
 * engine failure), and every earlier round branches on the check result,
 * sleeping on the durable clock before handing off. The computed summary Task
 * becomes a sealed action because its string formatting computes on the check
 * result, and computation on step results belongs in an action
 * implementation; inside the plan the check result is only ever passed.
 *
 * Deviations:
 * - `timeoutMs={30_000}` per task has no per-action equivalent in the flow
 *   DSL (GAPS.md GAP-5).
 * - The checker agent (bash tool) is a STUB (GAPS.md GAP-1).
 */
import * as NodeCrypto from "@effect/platform-node/NodeCrypto"
import { FlowEngine } from "@smthrs/engine"
import { Action, Flow, Interpreter, Sleep } from "@smthrs/flow"
import { Node } from "@smthrs/plan"
import * as Effect from "effect/Effect"
import * as Layer from "effect/Layer"
import * as Schema from "effect/Schema"

// zod: { satisfied, status, details, checkedAt }
const CheckResult = Schema.Struct({
  satisfied: Schema.Boolean,
  status: Schema.String,
  details: Schema.String,
  checkedAt: Schema.String
})

// zod: { passed, totalChecks, finalStatus, summary }
const GateResult = Schema.Struct({
  passed: Schema.Boolean,
  totalChecks: Schema.Number,
  finalStatus: Schema.String,
  summary: Schema.String
})

const GatePayload = Schema.Struct({
  condition: Schema.String,
  checkCmd: Schema.String,
  checkNumber: Schema.Number,
  maxChecks: Schema.Number,
  lastStatus: Schema.String
})

/** smithers: checker Agent with the bash tool. */
export const RunCheck = Action.make("gate/check", {
  payload: {
    condition: Schema.String,
    checkCmd: Schema.String,
    checkNumber: Schema.Number,
    lastStatus: Schema.String
  },
  success: CheckResult
})

/** smithers: the computed gate Task. */
export const Summarize = Action.make("gate/summarize", {
  payload: {
    passed: Schema.Boolean,
    totalChecks: Schema.Number,
    finalStatus: Schema.String
  },
  success: GateResult
})

type GateFlow = Flow.Flow<
  "gate/gate",
  typeof GatePayload,
  typeof GateResult,
  typeof Sleep.SleepRequestInvalid,
  | Action.Requirement<"gate/check">
  | Action.Requirement<"gate/summarize">
>

export const Gate: GateFlow = Flow.make("gate/gate", {
  payload: GatePayload,
  success: GateResult,
  error: Sleep.SleepRequestInvalid,
  body: ({ checkCmd, checkNumber, condition, lastStatus, maxChecks }) => {
    const check = RunCheck.call({ condition, checkCmd, checkNumber, lastStatus })
    // onMaxReached="return-last": the final allowed round settles with a
    // summary whatever the check said. The check's satisfied flag is passed
    // into the summary payload as a planned reference, never computed on.
    if (checkNumber >= maxChecks) {
      return check.pipe(
        Node.andThen((result) =>
          Summarize.call({
            passed: result.satisfied,
            totalChecks: checkNumber,
            finalStatus: result.status
          })
        )
      )
    }
    return check.pipe(
      Node.branch({
        if: (result) => result.satisfied,
        then: (result) =>
          Summarize.call({
            passed: true,
            totalChecks: checkNumber,
            finalStatus: result.status
          }),
        else: (result) =>
          Sleep.action.call({ millis: 5_000 }).pipe(
            Node.andThen(() =>
              Gate.to({
                condition,
                checkCmd,
                checkNumber: checkNumber + 1,
                maxChecks,
                lastStatus: result.status
              })
            )
          )
      })
    )
  }
})

/** STUB agent seam (GAPS.md GAP-1): satisfied on the third check. */
const implementations = Layer.mergeAll(
  RunCheck.toLayer(({ checkNumber }) =>
    Effect.succeed({
      satisfied: checkNumber >= 3,
      status: checkNumber >= 3 ? "green" : "pending",
      details: `check #${checkNumber}`,
      checkedAt: `t+${checkNumber}`
    })
  ),
  Summarize.toLayer(({ finalStatus, passed, totalChecks }) =>
    Effect.succeed({
      passed,
      totalChecks,
      finalStatus,
      summary: passed
        ? `Gate passed after ${totalChecks} check(s)`
        : `Gate timed out after ${totalChecks} check(s). Last status: ${finalStatus}`
    })
  ),
  Sleep.layer
)

const GateLayer = Layer.mergeAll(
  implementations,
  Interpreter.layer(Gate)
).pipe(
  Layer.provideMerge(Action.layerImplementations),
  Layer.provideMerge(FlowEngine.layerMemory),
  Layer.provideMerge(NodeCrypto.layer)
)

export const main: Effect.Effect<typeof GateResult.Type> = Gate.execute(
  {
    condition: "CI is green",
    checkCmd: "gh run list --limit 1",
    checkNumber: 1,
    maxChecks: 30,
    lastStatus: "not yet checked"
  },
  { executionId: "gate-1" }
).pipe(
  Effect.orDie,
  Effect.provide(GateLayer)
)

/**
 * Port of examples/fan-out-fan-in.jsx.
 *
 * Smithers shape: split Task, then `{split && <Parallel maxConcurrency={5}>}`
 * mapping `split.items` to one Task each (`continueOnFail`,
 * `timeoutMs={120_000}`), then a merge Task over the accumulated results.
 *
 * flows shape: plan width is fixed at plan time, so fanning out over
 * something a step discovered takes two rounds (Node.all's own doc says so:
 * "end the round and carry the list in the next flow's payload"). The Split
 * flow runs the splitter and hands off; the Process flow receives the items
 * as real payload data, builds a Node.all record with one process call per
 * item, and feeds the joined record into the merge action. `continueOnFail`
 * becomes `Node.catch` per item, recovering to a failed-status result.
 *
 * Deviations:
 * - `maxConcurrency` is not expressible; Node.all declares independence and
 *   the engine owns scheduling width (GAPS.md GAP-6).
 * - `timeoutMs` per task: no equivalent (GAPS.md GAP-5).
 * - Agents (splitter, processor, merger) are STUBs (GAPS.md GAP-1).
 */
import * as NodeCrypto from "@effect/platform-node/NodeCrypto"
import { FlowEngine } from "@smthrs/engine"
import { Action, Flow, Interpreter } from "@smthrs/flow"
import { Node } from "@smthrs/plan"
import * as Effect from "effect/Effect"
import * as Layer from "effect/Layer"
import * as Schema from "effect/Schema"

const WorkItem = Schema.Struct({
  id: Schema.String,
  input: Schema.String,
  context: Schema.String
})

// zod: splitSchema
const SplitResult = Schema.Struct({
  items: Schema.Array(WorkItem),
  totalItems: Schema.Number
})

// zod: processSchema (metrics omitted: z.record optional field)
const ProcessResult = Schema.Struct({
  itemId: Schema.String,
  output: Schema.String,
  status: Schema.Literals(["success", "failed"])
})

// zod: mergeSchema
const MergeResult = Schema.Struct({
  totalProcessed: Schema.Number,
  succeeded: Schema.Number,
  failed: Schema.Number,
  aggregatedOutput: Schema.String,
  summary: Schema.String
})

class ProcessFailed extends Schema.TaggedError<ProcessFailed>()(
  "fan-out-fan-in/ProcessFailed",
  { itemId: Schema.String, message: Schema.String }
) {}

/** smithers: splitter ClaudeCodeAgent. */
export const Split = Action.make("fan-out-fan-in/split", {
  payload: {
    input: Schema.String,
    operation: Schema.String,
    maxChunks: Schema.Number
  },
  success: SplitResult
})

/** smithers: processor ClaudeCodeAgent, one Task per item. */
export const ProcessItem = Action.make("fan-out-fan-in/process", {
  payload: {
    id: Schema.String,
    input: Schema.String,
    context: Schema.String,
    operation: Schema.String
  },
  success: ProcessResult,
  error: ProcessFailed
})

/** smithers: merger ClaudeCodeAgent over ctx.outputs.process. */
export const Merge = Action.make("fan-out-fan-in/merge", {
  payload: {
    results: Schema.Record(Schema.String, ProcessResult)
  },
  success: MergeResult
})

/**
 * Round two: the item list is real payload data here, so the fan-out width is
 * known at this round's plan time. One process call per item, each protected
 * by Node.catch (smithers `continueOnFail`), joined by Node.all, merged.
 */
export const ProcessAll = Flow.make("fan-out-fan-in/process-all", {
  payload: {
    items: Schema.Array(WorkItem),
    operation: Schema.String
  },
  success: MergeResult,
  body: ({ items, operation }) =>
    Node.all(
      Object.fromEntries(
        items.map((item) => [
          item.id,
          ProcessItem.call({
            id: item.id,
            input: item.input,
            context: item.context,
            operation
          }).pipe(
            // continueOnFail: a failed item becomes a failed-status result
            // instead of failing the round.
            Node.catch({
              onFailure: () =>
                Node.succeed({
                  itemId: item.id,
                  output: "",
                  status: "failed" as const
                })
            })
          )
        ])
      )
    ).pipe(
      Node.andThen((results) => Merge.call({ results }))
    )
})

/** Round one: split, then hand the discovered list to the fan-out round. */
export const FanOutFanIn = Flow.make("fan-out-fan-in/fan-out-fan-in", {
  payload: {
    input: Schema.String,
    operation: Schema.String,
    maxChunks: Schema.Number
  },
  success: MergeResult,
  body: ({ input, maxChunks, operation }) =>
    Split.call({ input, operation, maxChunks }).pipe(
      Node.andThen((split) => ProcessAll.to({ items: split.items, operation }))
    )
})

/** STUB agent seam (GAPS.md GAP-1). */
const implementations = Layer.mergeAll(
  Split.toLayer(({ input, maxChunks }) => {
    const items = input
      .split(/\d+\.\s+/)
      .map((chunk) => chunk.trim())
      .filter((chunk) => chunk.length > 0)
      .slice(0, maxChunks)
      .map((chunk, index) => ({
        id: `item-${index + 1}`,
        input: chunk,
        context: "sentence"
      }))
    return Effect.succeed({ items, totalItems: items.length })
  }),
  ProcessItem.toLayer(({ id, input }) =>
    Effect.succeed({
      itemId: id,
      output: `processed: ${input}`,
      status: "success" as const
    })
  ),
  Merge.toLayer(({ results }) => {
    const rows = Object.values(results)
    const succeeded = rows.filter((row) => row.status === "success").length
    return Effect.succeed({
      totalProcessed: rows.length,
      succeeded,
      failed: rows.length - succeeded,
      aggregatedOutput: rows.map((row) => row.output).join("\n"),
      summary: `${succeeded}/${rows.length} items succeeded`
    })
  })
)

const FanOutLayer = Layer.mergeAll(
  implementations,
  Interpreter.layer(FanOutFanIn),
  Interpreter.layer(ProcessAll)
).pipe(
  Layer.provideMerge(Action.layerImplementations),
  Layer.provideMerge(FlowEngine.layerMemory),
  Layer.provideMerge(NodeCrypto.layer)
)

export const main: Effect.Effect<typeof MergeResult.Type> = FanOutFanIn.execute(
  {
    input:
      "Analyze the sentiment of these three sentences: 1. I love Smithers! 2. AI orchestration is hard. 3. This TUI is amazing!",
    operation: "Analyze sentiment for each item independently.",
    maxChunks: 3
  },
  { executionId: "fan-out-fan-in-1" }
).pipe(
  Effect.orDie,
  Effect.provide(FanOutLayer)
)

/**
 * Port of examples/panel.jsx.
 *
 * Smithers shape: an input-configurable panel of specialist reviewers runs in
 * a static `<Parallel>`, then a moderator Task synthesizes
 * `ctx.outputs.specialistReview`.
 *
 * flows shape: the panel selection is flow payload, which is real data at
 * plan time, so the body maps over it and builds a `Node.all` record with one
 * review call per active specialist. The joined record feeds the synthesis
 * action. One flow, one round; no trampoline needed because nothing about the
 * width is discovered by a step.
 *
 * Deviations:
 * - The four specialist agents differ only by system prompt. In flows the
 *   prompt is implementation-side, so one review action takes role and focus
 *   as payload; the specialist table is plain data (GAPS.md GAP-1 for the
 *   agent seam itself).
 * - `timeoutMs={120_000}`: no equivalent (GAPS.md GAP-5).
 */
import * as NodeCrypto from "@effect/platform-node/NodeCrypto"
import { FlowEngine } from "@smthrs/engine"
import { Action, Flow, Interpreter } from "@smthrs/flow"
import { Node } from "@smthrs/plan"
import * as Effect from "effect/Effect"
import * as Layer from "effect/Layer"
import * as Schema from "effect/Schema"

const Verdict = Schema.Literals(["approve", "request-changes", "comment"])

const Finding = Schema.Struct({
  severity: Schema.Literals(["critical", "warning", "info"]),
  description: Schema.String,
  file: Schema.optional(Schema.String),
  suggestion: Schema.optional(Schema.String)
})

// zod: specialistReviewSchema
const SpecialistReview = Schema.Struct({
  role: Schema.String,
  verdict: Verdict,
  findings: Schema.Array(Finding),
  summary: Schema.String
})

// zod: synthesisSchema
const Synthesis = Schema.Struct({
  overallVerdict: Verdict,
  criticalIssues: Schema.Array(Schema.String),
  suggestions: Schema.Array(Schema.String),
  summary: Schema.String
})

const PanelKey = Schema.Literals([
  "security",
  "quality",
  "architecture",
  "performance"
])

/** smithers: makeSpecialist(role, focus) — the prompt varies, the step shape
